namespace Payments;

public interface IPaymentProcessor
{
    Task<ChargeResult> ProcessChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default);
    Task<RefundResult> ProcessRefundAsync(string chargeId, CancellationToken cancellationToken = default);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProcessor _processor;
    private readonly Dictionary<string, ChargeRecord> _charges = new();

    public PaymentGateway(IPaymentProcessor processor)
    {
        _processor = processor ?? throw new ArgumentNullException(nameof(processor));
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(cardToken))
            throw new ArgumentException("Card token is required.", nameof(cardToken));

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be positive.");

        if (amount > 999_999.99m)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount exceeds maximum allowed.");

        var result = await _processor.ProcessChargeAsync(cardToken, amount, cancellationToken);

        if (result.Success)
            _charges[result.ChargeId] = new ChargeRecord(result.ChargeId, cardToken, amount, false);

        return result;
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(chargeId))
            throw new ArgumentException("Charge ID is required.", nameof(chargeId));

        if (!_charges.TryGetValue(chargeId, out var charge))
            throw new InvalidOperationException($"Charge '{chargeId}' not found.");

        if (charge.Refunded)
            throw new InvalidOperationException($"Charge '{chargeId}' has already been refunded.");

        var result = await _processor.ProcessRefundAsync(chargeId, cancellationToken);

        if (result.Success)
            _charges[chargeId] = charge with { Refunded = true };

        return result;
    }

    public WebhookResult ProcessWebhook(string eventType, string chargeId)
    {
        if (string.IsNullOrWhiteSpace(eventType))
            throw new ArgumentException("Event type is required.", nameof(eventType));

        if (string.IsNullOrWhiteSpace(chargeId))
            throw new ArgumentException("Charge ID is required.", nameof(chargeId));

        return eventType switch
        {
            "charge.succeeded" => _charges.ContainsKey(chargeId)
                ? new WebhookResult(true, $"Charge {chargeId} confirmed.")
                : new WebhookResult(false, $"Unknown charge {chargeId}."),
            "charge.failed" => HandleFailedCharge(chargeId),
            "charge.disputed" => _charges.ContainsKey(chargeId)
                ? new WebhookResult(true, $"Dispute opened for {chargeId}.")
                : new WebhookResult(false, $"Unknown charge {chargeId}."),
            _ => new WebhookResult(false, $"Unrecognized event type '{eventType}'.")
        };
    }

    private WebhookResult HandleFailedCharge(string chargeId)
    {
        if (_charges.Remove(chargeId))
            return new WebhookResult(true, $"Charge {chargeId} removed after failure.");

        return new WebhookResult(false, $"Unknown charge {chargeId}.");
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);
public record WebhookResult(bool Handled, string Message);
internal record ChargeRecord(string ChargeId, string CardToken, decimal Amount, bool Refunded);

