namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProcessor _processor;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _processor = new FakePaymentProcessor();
        _gateway = new PaymentGateway(_processor);
    }

    // ───────────────────────── Constructor ─────────────────────────

    [TestMethod]
    public void Constructor_NullProcessor_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
        Assert.AreEqual("processor", ex.ParamName);
    }

    // ───────────────────────── ChargeAsync ─────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessfulCharge()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 50.00m);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ProcessorDeclines_ReturnsFailedCharge()
    {
        _processor.ShouldSucceed = false;

        var result = await _gateway.ChargeAsync("tok_declined", 100.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? cardToken)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10m));
        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_AmountExceedsMax_ThrowsArgumentOutOfRangeException()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", 1_000_000m));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_BoundaryAmount_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 999_999.99m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_SmallestValidAmount_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 0.01m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_CancellationRequested_ThrowsOperationCanceledException()
    {
        _processor.Delay = TimeSpan.FromSeconds(5);
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m, cts.Token));
    }

    // ───────────────────────── RefundAsync ─────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidCharge_ReturnsSuccessfulRefund()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 75.00m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ProcessorDeclines_ReturnsFailedRefund()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 50.00m);
        _processor.ShouldSucceed = false;

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsFalse(refund.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("  ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
        Assert.AreEqual("chargeId", ex.ParamName);
    }

    [TestMethod]
    public async Task RefundAsync_UnknownCharge_ThrowsInvalidOperationException()
    {
        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync("ch_nonexistent"));
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefunded_ThrowsInvalidOperationException()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 100.00m);
        await _gateway.RefundAsync(charge.ChargeId);

        var ex = await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync(charge.ChargeId));
        Assert.Contains("already been refunded", ex.Message);
    }

    [TestMethod]
    public async Task RefundAsync_FailedCharge_IsNotRecorded_ThrowsInvalidOperation()
    {
        _processor.ShouldSucceed = false;
        var charge = await _gateway.ChargeAsync("tok_declined", 25.00m);

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync(charge.ChargeId));
    }

    [TestMethod]
    public async Task RefundAsync_CancellationRequested_ThrowsOperationCanceledException()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 30.00m);
        _processor.Delay = TimeSpan.FromSeconds(5);
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.RefundAsync(charge.ChargeId, cts.Token));
    }

    // ───────────────────────── ProcessWebhook ─────────────────────────

    [TestMethod]
    public async Task ProcessWebhook_ChargeSucceeded_KnownCharge_ReturnsHandled()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 60.00m);

        var result = _gateway.ProcessWebhook("charge.succeeded", charge.ChargeId);

        Assert.IsTrue(result.Handled);
        Assert.Contains("confirmed", result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_ChargeSucceeded_UnknownCharge_ReturnsNotHandled()
    {
        var result = _gateway.ProcessWebhook("charge.succeeded", "ch_unknown");

        Assert.IsFalse(result.Handled);
        Assert.Contains("Unknown charge", result.Message);
    }

    [TestMethod]
    public async Task ProcessWebhook_ChargeFailed_RemovesCharge()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 40.00m);

        var result = _gateway.ProcessWebhook("charge.failed", charge.ChargeId);

        Assert.IsTrue(result.Handled);
        Assert.Contains("removed", result.Message);

        // Charge should no longer exist — refund should fail
        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync(charge.ChargeId));
    }

    [TestMethod]
    public void ProcessWebhook_ChargeFailed_UnknownCharge_ReturnsNotHandled()
    {
        var result = _gateway.ProcessWebhook("charge.failed", "ch_unknown");

        Assert.IsFalse(result.Handled);
    }

    [TestMethod]
    public async Task ProcessWebhook_ChargeDisputed_KnownCharge_ReturnsHandled()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 200.00m);

        var result = _gateway.ProcessWebhook("charge.disputed", charge.ChargeId);

        Assert.IsTrue(result.Handled);
        Assert.Contains("Dispute", result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_ChargeDisputed_UnknownCharge_ReturnsNotHandled()
    {
        var result = _gateway.ProcessWebhook("charge.disputed", "ch_unknown");

        Assert.IsFalse(result.Handled);
    }

    [TestMethod]
    public void ProcessWebhook_UnrecognizedEvent_ReturnsNotHandled()
    {
        var result = _gateway.ProcessWebhook("customer.created", "ch_1");

        Assert.IsFalse(result.Handled);
        Assert.Contains("Unrecognized", result.Message);
    }

    [TestMethod]
    [DataRow(null, "ch_1", "eventType")]
    [DataRow("", "ch_1", "eventType")]
    [DataRow("charge.succeeded", null, "chargeId")]
    [DataRow("charge.succeeded", "", "chargeId")]
    public void ProcessWebhook_InvalidArgs_ThrowsArgumentException(
        string? eventType, string? chargeId, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, chargeId!));
        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ───────────────────── Integration / Workflow ─────────────────────

    [TestMethod]
    public async Task FullWorkflow_ChargeThenRefund_Succeeds()
    {
        var charge = await _gateway.ChargeAsync("tok_visa", 150.00m);
        Assert.IsTrue(charge.Success);

        var webhook = _gateway.ProcessWebhook("charge.succeeded", charge.ChargeId);
        Assert.IsTrue(webhook.Handled);

        var refund = await _gateway.RefundAsync(charge.ChargeId);
        Assert.IsTrue(refund.Success);
    }

    [TestMethod]
    public async Task MultipleCharges_EachGetsUniqueId()
    {
        var charge1 = await _gateway.ChargeAsync("tok_a", 10m);
        var charge2 = await _gateway.ChargeAsync("tok_b", 20m);
        var charge3 = await _gateway.ChargeAsync("tok_c", 30m);

        Assert.AreNotEqual(charge1.ChargeId, charge2.ChargeId);
        Assert.AreNotEqual(charge2.ChargeId, charge3.ChargeId);
        Assert.AreNotEqual(charge1.ChargeId, charge3.ChargeId);
    }
}

